/**
 * Generates editable API test files from discovered endpoints: Jest, Vitest or Mocha with
 * Supertest for Node apps, and JUnit 5 with MockMvc (`@WebMvcTest`) for Spring controllers.
 *
 * Expectations are only written where the code supports them: a 404 test exists only if the
 * handler sends a 404, response properties come from the inferred response shape, and auth tests
 * only for endpoints with detected auth. Everything else is a TODO or a pending test (`it.todo`),
 * so a generated file never passes by accident.
 */
import * as path from 'path';
import { flatten, statusCodes, successShape } from './shapes';
import type { Endpoint, EndpointParameter } from './types';

export type TestRunner = 'jest' | 'vitest' | 'mocha' | 'junit';

export interface NodeTestProject {
  kind: 'node';
  root: string;
  runner: Exclude<TestRunner, 'junit'>;
  /** Runner chosen because none is installed. */
  runnerMissing: boolean;
  supertest: boolean;
  esm: boolean;
  typescript: boolean;
  /** Folder for new test files. */
  testDir: string;
  /** The module exporting the app (`module.exports = app`, `export default app`). */
  app?: { file: string; exportName: string; lib: 'express' | 'fastify' | 'koa' };
  /** NestJS root module file (`src/app.module.ts`). */
  nestAppModule?: string;
}

export interface JavaTestProject {
  kind: 'java';
  root: string;
  /** `src/test/java`. */
  testDir: string;
  packageName: string;
  /** Controller fields (name → type), mocked with `@MockitoBean`/`@MockBean`. */
  dependencies: Record<string, string>;
  /** Spring Boot version from the build file, to choose `@MockitoBean` (3.4+) or `@MockBean`. */
  springBootVersion?: string;
  /** `server.servlet.context-path`: MockMvc paths do not include it. */
  contextPath?: string;
  /** Spring Security is configured: requests need a user. */
  security: boolean;
}

export type TestProject = NodeTestProject | JavaTestProject;

export interface GeneratedTest {
  file: string;
  content: string;
  runner: TestRunner;
  /** Setup the user still has to do (missing runner, app not exported, fixtures). */
  warnings: string[];
}

/** Chooses a runner and module style from `package.json`. */
export function detectNodeSetup(pkg: Record<string, unknown> | undefined, hasTsconfig: boolean): Pick<NodeTestProject, 'runner' | 'runnerMissing' | 'supertest' | 'esm' | 'typescript'> {
  const deps = { ...(obj(pkg?.dependencies) ?? {}), ...(obj(pkg?.devDependencies) ?? {}) };
  const has = (name: string): boolean => Object.prototype.hasOwnProperty.call(deps, name);
  const runner = has('vitest') ? 'vitest' : has('jest') || has('ts-jest') ? 'jest' : has('mocha') ? 'mocha' : 'jest';
  return {
    runner,
    runnerMissing: !has('vitest') && !has('jest') && !has('ts-jest') && !has('mocha'),
    supertest: has('supertest'),
    esm: pkg?.type === 'module',
    typescript: hasTsconfig || has('typescript'),
  };
}

export function generateTests(endpoints: Endpoint[], project: TestProject, name: string): GeneratedTest {
  return project.kind === 'java' ? javaTests(endpoints, project, name) : nodeTests(endpoints, project, name);
}

// ---------------------------------------------------------------------------------------------
// Node (Supertest)
// ---------------------------------------------------------------------------------------------

function nodeTests(endpoints: Endpoint[], p: NodeTestProject, name: string): GeneratedTest {
  const ext = p.typescript ? 'ts' : 'js';
  const file = path.join(p.testDir, `${safeName(name)}.api.test.${ext}`);
  const warnings: string[] = [];
  const imports = p.typescript || p.esm;
  const lines: string[] = [
    `// API tests for ${name}, generated by API Shadow from static analysis.`,
    '// Review every expectation: they reflect what the code appears to do, not a specification.',
    '',
  ];
  if (p.runner === 'vitest') lines.push(`import { describe, it, expect${endpoints.some(needsSetup) ? ', beforeAll, afterAll' : ''} } from 'vitest';`);
  lines.push(imports ? `import request from 'supertest';` : `const request = require('supertest');`);
  if (!p.supertest) warnings.push('Supertest is not installed: run `npm install --save-dev supertest`' + (p.typescript ? ' @types/supertest' : '') + '.');
  if (p.runnerMissing) warnings.push(`No test runner found in package.json; the file is written for ${p.runner}. Install it (\`npm install --save-dev ${p.runner}\`) or change the imports.`);
  const nest = endpoints.every((e) => e.framework === 'nestjs');
  let server = 'app';
  let setup: string[] = [];
  if (nest) {
    const mod = p.nestAppModule ? importPath(file, p.nestAppModule) : undefined;
    if (!mod) warnings.push('AppModule was not found; set the import of AppModule.');
    lines.push(`import { Test } from '@nestjs/testing';`, `import type { INestApplication } from '@nestjs/common';`, mod ? `import { AppModule } from '${mod}';` : `// TODO: import { AppModule } from '<path to app.module>';`);
    setup = [
      `  let app${p.typescript ? ': INestApplication' : ''};`,
      '',
      '  beforeAll(async () => {',
      `    const moduleRef = await Test.createTestingModule({ imports: [${mod ? 'AppModule' : '/* AppModule */'}] }).compile();`,
      '    app = moduleRef.createNestApplication();',
      '    // TODO: apply the same global prefix, pipes and versioning as main.ts.',
      '    await app.init();',
      '  });',
      '',
      '  afterAll(async () => {',
      '    await app.close();',
      '  });',
      '',
    ];
    server = 'app.getHttpServer()';
    if (!p.typescript) lines.splice(lines.indexOf(`import type { INestApplication } from '@nestjs/common';`), 1);
  } else if (p.app) {
    const rel = importPath(file, p.app.file);
    const local = p.app.lib === 'fastify' ? 'app' : 'app';
    if (p.app.exportName === 'default') lines.push(imports ? `import ${local} from '${rel}';` : `const ${local} = require('${rel}');`);
    else if (p.app.exportName === '*cjs') lines.push(imports ? `import ${local} from '${rel}';` : `const ${local} = require('${rel}');`);
    else lines.push(imports ? `import { ${p.app.exportName} as ${local} } from '${rel}';` : `const { ${p.app.exportName}: ${local} } = require('${rel}');`);
    if (p.app.lib === 'fastify') {
      setup = ['  beforeAll(async () => {', '    await app.ready();', '  });', '', '  afterAll(async () => {', '    await app.close();', '  });', ''];
      server = 'app.server';
    } else if (p.app.lib === 'koa') {
      server = 'app.callback()';
    }
  } else {
    warnings.push('The app is not exported from any module API Shadow could find. Export it (`module.exports = app` or `export default app`) without calling listen() on import, then fix the import below.');
    lines.push(`// TODO: export the app from its module and import it here, e.g. ${imports ? "import app from '../src/app';" : "const app = require('../src/app');"}`, imports ? `const app${p.typescript ? ': any' : ''} = undefined;` : 'const app = undefined;');
  }
  if (p.runner === 'mocha') {
    lines.push(imports ? `import { expect } from 'chai';` : `const { expect } = require('chai');`);
    warnings.push('Mocha tests use chai for assertions (`npm install --save-dev chai`).');
  }
  lines.push('');
  const groups = endpoints.map((e) => nodeDescribe(e, server, p.runner)).join('\n\n');
  if (setup.length) {
    lines.push(`describe('${esc(name)} API', () => {`, ...setup, indent(groups, 1), '});', '');
  } else {
    lines.push(groups, '');
  }
  if (endpoints.some((e) => e.parameters.some((x) => x.in === 'path') || /[:{]/.test(e.path))) warnings.push('Path parameters use placeholder values (`1`); replace them with ids of test fixtures.');
  return { file, content: lines.join('\n'), runner: p.runner, warnings };
}

function needsSetup(e: Endpoint): boolean {
  return e.framework === 'nestjs' || e.framework === 'fastify';
}

function nodeDescribe(e: Endpoint, server: string, runner: NodeTestProject['runner']): string {
  const m = e.method === 'ALL' ? 'get' : e.method.toLowerCase();
  const url = samplePath(e.path, e.parameters);
  const statuses = statusCodes(e);
  const success = statuses.find((s) => s >= 200 && s < 300) ?? (e.framework === 'nestjs' && e.method === 'POST' ? 201 : 200);
  const shape = successShape(e);
  const write = ['POST', 'PUT', 'PATCH'].includes(e.method);
  const call = (extra = ''): string => `await request(${server}).${m}('${esc(url)}')${extra}`;
  const expectStatus = (s: number | string): string => (runner === 'mocha' ? `expect(res.status).to.equal(${s});` : `expect(res.status).toBe(${s});`);
  const todo = (title: string): string => (runner === 'mocha' ? `it('${esc(title)}');` : `it.todo('${esc(title)}');`);
  const tests: string[] = [];

  const body: string[] = [];
  body.push(`  it('responds ${success} for a valid request', async () => {`);
  if (url !== e.path.replace(/\/+$/, '') || /[:{]/.test(e.path)) body.push('    // TODO: use the id of a record created in test setup.');
  if (e.auth?.status === 'protected' || e.auth?.status === 'central') body.push(`    // TODO: authenticate the request (detected: ${e.auth.via.join(', ') || e.auth.status}).`);
  body.push(`    const res = ${call(write ? `.send(${requestBodySample(e)})` : '')};`);
  body.push(`    ${expectStatus(success)}`);
  for (const line of shapeAssertions(shape, runner)) body.push(`    ${line}`);
  body.push('  });');
  tests.push(body.join('\n'));

  if (statuses.includes(404)) {
    tests.push(
      [
        `  it('responds 404 when the resource does not exist', async () => {`,
        `    const res = ${call(write ? `.send(${requestBodySample(e)})` : '').replace(`'${esc(url)}'`, `'${esc(samplePath(e.path, e.parameters, 'missing'))}'`)};`,
        `    ${expectStatus(404)}`,
        '  });',
      ].join('\n'),
    );
  } else if (/[:{]/.test(e.path)) {
    tests.push(`  ${todo('responds with an error when the resource does not exist (the handler does not send a 404 that API Shadow could see)')}`);
  }
  if (write && e.validation?.status === 'validated') {
    tests.push([`  it('rejects an invalid request body', async () => {`, `    const res = ${call('.send({})')};`, `    ${expectStatus(400)}`, '  });'].join('\n'));
  } else if (write) {
    tests.push(`  ${todo('rejects a request body with missing required fields (no validation was detected)')}`);
  }
  const required = e.parameters.filter((x) => x.in === 'query' && x.required);
  if (required.length) {
    tests.push(`  ${todo(`responds 400 without the required query parameter(s) ${required.map((x) => x.name).join(', ')}`)}`);
  }
  if (e.auth?.status === 'protected' || e.auth?.status === 'central') {
    const assertion = runner === 'mocha' ? 'expect([401, 403]).to.include(res.status);' : 'expect([401, 403]).toContain(res.status);';
    tests.push([`  it('rejects unauthenticated requests', async () => {`, `    const res = ${call()};`, `    ${assertion}`, '  });'].join('\n'));
  }
  tests.push(`  ${todo('responds 500 when a dependency fails (mock the service to throw)')}`);
  return [`describe('${esc(`${e.method} ${e.path}`)}', () => {`, tests.join('\n\n'), '});'].join('\n');
}

/** Assertions for known fields of the inferred response; unknown parts are left out. */
function shapeAssertions(shape: ReturnType<typeof successShape>, runner: NodeTestProject['runner']): string[] {
  if (!shape) return ['// TODO: assert the response body; its shape could not be inferred.'];
  const out: string[] = [];
  if (shape.t === 'array') out.push(runner === 'mocha' ? 'expect(res.body).to.be.an(\'array\');' : 'expect(Array.isArray(res.body)).toBe(true);');
  const fields = [...flatten(shape).values()].filter((f) => !f.path.includes('[]') && !f.prop.optional && f.path.split('.').length <= 3).slice(0, 12);
  for (const f of fields) {
    const access = f.path.split('.').map((k) => (/^[A-Za-z_$][\w$]*$/.test(k) ? `.${k}` : `[${JSON.stringify(k)}]`)).join('');
    if (runner === 'mocha') {
      out.push(`expect(res.body).to.have.nested.property('${esc(f.path)}');`);
    } else {
      out.push(`expect(res.body).toHaveProperty(${JSON.stringify(f.path.split('.'))});`);
    }
    const t = f.shape.t;
    if (t === 'string' || t === 'number' || t === 'boolean') out.push(runner === 'mocha' ? `expect(res.body${access}).to.be.a('${t}');` : `expect(typeof res.body${access}).toBe('${t}');`);
  }
  if (out.length === 0) out.push('// TODO: assert the response body.');
  return out;
}

function requestBodySample(e: Endpoint): string {
  return e.requestBodyType ? `{ /* TODO: a valid ${e.requestBodyType} */ }` : '{ /* TODO: a valid request body */ }';
}

// ---------------------------------------------------------------------------------------------
// Java (MockMvc)
// ---------------------------------------------------------------------------------------------

function javaTests(endpoints: Endpoint[], p: JavaTestProject, controller: string): GeneratedTest {
  const cls = `${safeName(controller)}ApiTest`;
  const file = path.join(p.testDir, ...p.packageName.split('.').filter(Boolean), `${cls}.java`);
  const warnings: string[] = [];
  const mockito = isAtLeast(p.springBootVersion, 3, 4);
  const mockAnnotation = mockito ? 'MockitoBean' : 'MockBean';
  const deps = Object.entries(p.dependencies).filter(([, type]) => /(Service|Repository|Client|Gateway|Facade|Manager|UseCase|Port|Mapper)$/.test(type));
  const lines: string[] = [];
  if (p.packageName) lines.push(`package ${p.packageName};`, '');
  lines.push(
    'import org.junit.jupiter.api.Test;',
    'import org.springframework.beans.factory.annotation.Autowired;',
    'import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;',
    mockito ? 'import org.springframework.test.context.bean.override.mockito.MockitoBean;' : 'import org.springframework.boot.test.mock.mockito.MockBean;',
    'import org.springframework.http.MediaType;',
    'import org.springframework.test.web.servlet.MockMvc;',
  );
  if (p.security) lines.push('import org.springframework.security.test.context.support.WithMockUser;');
  lines.push(
    '',
    'import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;',
    'import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;',
    '',
    `/** API tests for ${controller}, generated by API Shadow from static analysis. Review every expectation. */`,
    `@WebMvcTest(${controller}.class)`,
    `class ${cls} {`,
    '',
    '    @Autowired',
    '    private MockMvc mockMvc;',
    '',
  );
  for (const [field, type] of deps) lines.push(`    @${mockAnnotation}`, `    private ${type} ${field};`, '');
  if (deps.length === 0) warnings.push(`No service fields were found on ${controller}; add @${mockAnnotation} fields for its dependencies.`);
  if (p.security) warnings.push('Spring Security is configured: tests use @WithMockUser. Requires spring-security-test.');
  if (p.contextPath) warnings.push(`MockMvc paths exclude the context path ${p.contextPath}.`);
  const used = new Set<string>();
  for (const e of endpoints) {
    const base = methodName(e, used);
    const m = e.method === 'ALL' ? 'get' : e.method.toLowerCase();
    const { template, args } = javaPath(stripContext(e.path, p.contextPath), e.parameters);
    const perform = `${m}("${template.replace(/"/g, '\\"')}"${args.length ? ', ' + args.join(', ') : ''})`;
    const statuses = statusCodes(e);
    const success = statuses.find((s) => s >= 200 && s < 300) ?? 200;
    const write = ['POST', 'PUT', 'PATCH'].includes(e.method);
    const content = write ? `\n                .contentType(MediaType.APPLICATION_JSON)\n                .content("{}") // TODO: a valid ${e.requestBodyType ?? 'request body'}` : '';
    const annotations = p.security ? ['    @Test', '    @WithMockUser'] : ['    @Test'];
    lines.push(
      ...annotations,
      `    void ${base}_respondsOk() throws Exception {`,
      `        // TODO: stub the services, e.g. when(${deps[0]?.[0] ?? 'service'}.someMethod(...)).thenReturn(...);`,
      `        mockMvc.perform(${perform}${content})`,
      `                .andExpect(status().${statusMatcher(success)})${javaJsonAssertions(e)};`,
      '    }',
      '',
    );
    if (statuses.includes(404) || e.parameters.some((x) => x.in === 'path')) {
      lines.push(
        ...annotations,
        `    void ${base}_respondsNotFound() throws Exception {`,
        statuses.includes(404) ? '        // The handler sends 404 for a missing resource.' : '        // TODO: confirm how a missing resource is reported (no 404 was found in the handler).',
        `        // TODO: make the service report that the resource does not exist.`,
        `        mockMvc.perform(${perform}${content})`,
        '                .andExpect(status().isNotFound());',
        '    }',
        '',
      );
    }
    if (write && e.validation?.status === 'validated') {
      lines.push(
        ...annotations,
        `    void ${base}_rejectsInvalidBody() throws Exception {`,
        `        mockMvc.perform(${m}("${template.replace(/"/g, '\\"')}"${args.length ? ', ' + args.join(', ') : ''})`,
        '                .contentType(MediaType.APPLICATION_JSON)',
        '                .content("{}"))',
        '                .andExpect(status().isBadRequest());',
        '    }',
        '',
      );
    }
    const required = e.parameters.filter((x) => x.in === 'query' && x.required);
    if (required.length) {
      lines.push(
        ...annotations,
        `    void ${base}_requiresQueryParameters() throws Exception {`,
        `        // Required: ${required.map((x) => x.name).join(', ')}`,
        `        mockMvc.perform(${perform})`,
        '                .andExpect(status().isBadRequest());',
        '    }',
        '',
      );
    }
    if (p.security || e.auth?.status === 'protected') {
      lines.push(
        '    @Test',
        `    void ${base}_rejectsAnonymous() throws Exception {`,
        `        mockMvc.perform(${perform}${content})`,
        '                .andExpect(status().is4xxClientError());',
        '    }',
        '',
      );
    }
  }
  if (lines[lines.length - 1] === '') lines.pop();
  lines.push('}', '');
  if (endpoints.some((e) => e.parameters.some((x) => x.in === 'path'))) warnings.push('Path variables use placeholder values (`1`).');
  return { file, content: lines.join('\n'), runner: 'junit', warnings };
}

function javaJsonAssertions(e: Endpoint): string {
  const shape = successShape(e);
  if (!shape) return '';
  const root = shape.t === 'array' ? '$[0]' : '$';
  const target = shape.t === 'array' ? shape.items : shape;
  if (!target || target.t !== 'object') return shape.t === 'array' ? '\n                .andExpect(jsonPath("$").isArray())' : '';
  const fields = Object.keys(target.props).slice(0, 8);
  const lines = shape.t === 'array' ? ['\n                .andExpect(jsonPath("$").isArray())'] : [];
  // Array responses may be empty with mocked services; assert item fields only as a hint.
  for (const f of fields) lines.push(`\n                ${shape.t === 'array' ? '// ' : ''}.andExpect(jsonPath("${root}.${f}").exists())`);
  return lines.join('');
}

function statusMatcher(s: number): string {
  switch (s) {
    case 200:
      return 'isOk()';
    case 201:
      return 'isCreated()';
    case 202:
      return 'isAccepted()';
    case 204:
      return 'isNoContent()';
    default:
      return `is(${s})`;
  }
}

function javaPath(p: string, params: EndpointParameter[]): { template: string; args: string[] } {
  const args: string[] = [];
  const template = p.replace(/\{([^}:]+)(:[^}]*)?\}/g, (_m, name: string) => {
    const param = params.find((x) => x.name === name);
    args.push(/^(String|UUID)$/.test(param?.type ?? '') ? '"1"' : '1');
    return `{${name}}`;
  });
  return { template, args };
}

function stripContext(p: string, ctx: string | undefined): string {
  if (!ctx || ctx === '/') return p;
  const c = ctx.replace(/\/+$/, '');
  return p.startsWith(c + '/') ? p.slice(c.length) : p;
}

function methodName(e: Endpoint, used: Set<string>): string {
  const words = e.path
    .replace(/\{[^}]+\}|:[\w]+/g, 'by')
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .slice(-3);
  let base = [e.method.toLowerCase(), ...words.map((w) => w[0].toUpperCase() + w.slice(1))].join('');
  base = base.replace(/^[^a-z]/, 'm');
  let n = base;
  for (let i = 2; used.has(n); i++) n = `${base}${i}`;
  used.add(n);
  return n;
}

// ---------------------------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------------------------

/** `/users/:id(\d+)` → `/users/1`; `{id}` → `1`; regex and wildcard routes keep a TODO marker. */
export function samplePath(p: string, params: EndpointParameter[], variant: 'valid' | 'missing' = 'valid'): string {
  const value = (name: string): string => {
    const t = params.find((x) => x.name === name)?.type ?? '';
    if (variant === 'missing') return /^(String|string|UUID)$/.test(t) ? 'does-not-exist' : '999999';
    return /^(String|string|UUID)$/.test(t) ? 'example' : '1';
  };
  return (
    p
      .replace(/:(\w+)(\([^)]*\))?\??/g, (_m, name: string) => value(name))
      .replace(/\{(\w+)(:[^}]*)?\}/g, (_m, name: string) => value(name))
      .replace(/\$\{[^}]*\}/g, 'TODO')
      .replace(/\*+/g, 'any')
      .replace(/ ~ .*$/, '/TODO') || '/'
  );
}

function importPath(fromFile: string, target: string): string {
  let rel = path.relative(path.dirname(fromFile), target).split(path.sep).join('/');
  rel = rel.replace(/\.(ts|tsx|mts|cts)$/, '').replace(/\/index$/, '');
  return rel.startsWith('.') ? rel : `./${rel}`;
}

function safeName(name: string): string {
  return name.replace(/\.[^.]+$/, '').replace(/[^A-Za-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '') || 'api';
}

function esc(s: string): string {
  return s.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
}

function indent(text: string, levels: number): string {
  const pad = '  '.repeat(levels);
  return text
    .split('\n')
    .map((l) => (l ? pad + l : l))
    .join('\n');
}

function obj(v: unknown): Record<string, unknown> | undefined {
  return typeof v === 'object' && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : undefined;
}

function isAtLeast(version: string | undefined, major: number, minor: number): boolean {
  const m = /^(\d+)\.(\d+)/.exec(version ?? '');
  if (!m) return false;
  return Number(m[1]) > major || (Number(m[1]) === major && Number(m[2]) >= minor);
}

/**
 * The file name to write a generated test to without overwriting anything: the suggested name,
 * else `x.api.2.test.js` (or `XApiTest2.java`), and so on.
 */
export async function nextFreeName(file: string, exists: (file: string) => Promise<boolean>): Promise<string> {
  if (!(await exists(file))) return file;
  const java = file.endsWith('.java');
  const m = /^(.*?)((\.api)?\.test)?(\.[^.]+)$/.exec(file);
  const [stem, mid, ext] = m ? [m[1], m[2] ?? '', m[4]] : [file, '', ''];
  for (let i = 2; i < 100; i++) {
    const candidate = java ? `${stem}${i}${ext}` : `${stem}${mid ? mid.replace('.test', `.${i}.test`) : `.${i}`}${ext}`;
    if (!(await exists(candidate))) return candidate;
  }
  throw new Error(`Could not find a free file name for ${file}`);
}
